SELECT CASE WHEN salary >= 161000 THEN 'LARGE' ELSE 'SMALL' END AS salary_tier, COUNT(DISTINCT level) AS distinct_levels, AVG(salary) AS avg_salary, APPROX_PERCENTILE(salary, 0.95) AS salary_p95, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN level = 'L5' THEN 1 END), 0), 2) AS salary_per_l5, SIZE(COLLECT_SET(job_title)) AS num_job_titles FROM employees GROUP BY CASE WHEN salary >= 161000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY avg_salary DESC NULLS LAST
